"Es kommen nur <0>gerade Potenzen</0> von {1} vor — Substitution {2}:": "Vyskytují se jen <0>sudé mocniny</0> {1} — substituce {2}:",
"Es werden nur Beschriftungstexte gesendet – Zahlen, Formeln und eigene Eingaben bleiben im Browser.": "Odesílají se pouze popisky – čísla, vzorce a vlastní zadání zůstávají v prohlížeči.",
