"Fläche zwischen zwei Funktionsgraphen. Man zieht die untere Funktion von der oberen ab und integriert. Vorzeichen beachten — bei Vorzeichenwechsel der Differenz aufteilen.": "Plocha mezi dvěma grafy funkcí. Dolní funkce se odečte od horní a výsledek se zintegruje. Pozor na znaménka — při změně znaménka rozdílu interval rozdělit.",
"Fläche zwischen {0}=x² und {1}=x: A = ∫[{2}] (x−x²)dx = {3}/{4}": "Plocha mezi {0}=x² a {1}=x: A = ∫[{2}] (x−x²)dx = {3}/{4}",
"Fläche ≈ {0}": "Plocha ≈ {0}",
"Fläche ≈ {0} <1>(numerische Näherung)</1>": "Plocha ≈ {0} <1>(numerická aproximace)</1>",
"Flächeninhalt zwischen Graphen": "Obsah plochy mezi grafy",
"Form aufschalten, dann a, b, c bzw. a, v, h oben mit den Schiebereglern verändern.": "Přidejte tvar a pak měňte a, b, c (nebo a, v, h) posuvníky nahoře.",
"Form aufschalten, dann a, b, c und d oben mit den Schiebereglern verändern (a = Amplitude, b = Frequenz, c = Phasenverschiebung, d = Verschiebung nach oben/unten).": "Aktivujte tvar a poté nahoře upravte a, b, c a d pomocí posuvníků (a = amplituda, b = frekvence, c = fázový posun, d = posun nahoru/dolů).",
"Formen (Schieberegler)": "Tvary (posuvníky)",
"Freie Punkte": "Volné body",
"Funktion": "Funkce",
"Funktion eingeben und aufschalten: Punkt A und Punkt B sind beide ziehbar. Ziehe A und B nahe zusammen — der Differenzenquotient nähert sich dann dem Differentialquotienten (der Ableitung) an.": "Zadejte funkci a aktivujte ji: bod A i bod B lze oba posouvat. Přibližte A a B k sobě — diferenční podíl se pak blíží diferenciálnímu podílu (derivaci).",
"Funktion eingeben und aufschalten: die Intervallgrenzen a und b sind ziehbar. Ober-/Untersumme zwischen f und der x-Achse — erhöhe n, um dich dem exakten Integral anzunähern.": "Zadejte funkci a aktivujte ji: hranice intervalu a a b lze posouvat. Horní/dolní součet mezi f a osou x — zvyšte n pro přiblížení k přesné hodnotě integrálu.",
"Funktion eingeben, Randart wählen und aufschalten: die Intervallgrenzen a und b sind ziehbar (und frei eintippbar).": "Zadejte funkci, zvolte typ hranice a aktivujte: hranice intervalu a a b lze posouvat (a volně zadávat).",
"Funktion, bei der die Variable im Exponenten steht. Für b {0} {1}: exponentielles Wachstum. Für {2} {3} b {4} {5}: exponentieller Zerfall. Immer positiv, keine Nullstelle. Definitionsbereich: ℝ.": "Funkce, u které je proměnná v exponentu. Pro b {0} {1}: exponenciální růst. Pro {2} {3} b {4} {5}: exponenciální pokles. Vždy kladná, bez nulového bodu. Definiční obor: ℝ.",
"Funktionenplotter": "Plotter funkcí",
"Funktionsbeschriftung im Plot": "Popisky funkcí v grafu",
"Funktionstyp: {0} = {1}·{2}ˣ": "Typ funkce: {0} = {1}·{2}ˣ",
"Fülle mindestens {0} der {1} Felder aus — das leere Feld wird automatisch berechnet.": "Vyplňte alespoň {0} z {1} polí — prázdné pole se vypočte automaticky.",
"Für die Senkrechte: Punkt und Gerade im Plot wählen. Für die Mittelsenkrechte: zwei Punkte wählen. Inkl. Lösungsweg und Beziehung der Steigungen (m₁·m₂ = −{0}).": "Pro kolmici: vyberte bod a přímku v grafu. Pro osu úsečky: vyberte dva body. Včetně postupu řešení a vztahu mezi směrnicemi (m₁·m₂ = −{0}).",
"Für diese Funktion konnte keine elementare Stammfunktion gefunden werden.": "Pro tuto funkci se nepodařilo najít elementární primitivní funkci.",
"Für n gerade: achsensymmetrisch, Definitionsbereich ℝ. Für n ungerade: punktsymmetrisch, Definitionsbereich ℝ. Für n {0} {1}: Pol bei x = {2}, hyperbelartig.": "Pro n sudé: souměrná podle osy, definiční obor ℝ. Pro n liché: souměrná podle bodu, definiční obor ℝ. Pro n {0} {1}: pól v x = {2}, tvar hyperboly.",
"Für x → {0}: Zähler bleibt konstant ({1}), Nenner wächst über alle Grenzen (Wurzelterm dominiert)": "Pro x → {0}: čitatel zůstává konstantní ({1}), jmenovatel roste nade všechny meze (dominuje odmocninný člen)",
"Für x → {0}: Zähler und Nenner wachsen beide linear in x — das Verhältnis der Leitkoeffizienten ergibt den Grenzwert:": "Pro x → {0}: čitatel i jmenovatel rostou lineárně v x — poměr vedoucích koeficientů dává limitu:",
"Für x → ±∞: {0}/({1}) → {2}": "Pro x → ±∞: {0}/({1}) → {2}",
"Für {0} strebt der Summand {1} gegen {2} (Exponentialfunktion mit abnehmendem Exponenten). Es bleibt der Rest:": "Pro {0} se sčítanec {1} blíží k {2} (exponenciální funkce s klesajícím exponentem). Zbývá zbytek:",
"Gebrochen-rationale Funktion": "Racionální lomená funkce",
"Gekürzt (für x ≠ {0}): {1} = [{2}] / [{3}]": "Po zkrácení (pro x ≠ {0}): {1} = [{2}] / [{3}]",
"Gekürzte Funktion": "Zkrácená funkce",
"Gemeinsamer Punkt zweier Graphen. Berechnung durch Gleichsetzen: {0} = {1} nach x auflösen, dann y = {2} berechnen.": "Společný bod dvou grafů. Výpočet porovnáním: {0} = {1} vyřešit vzhledem k x, pak vypočítat y = {2}.",
"Geometrische Darstellung der Steigung am Graphen: Man wählt zwei Punkte, zieht eine waagrechte Strecke (Δx) und eine senkrechte Strecke (Δy). Die Steigung ist m = Δy/Δx.": "Geometrické znázornění směrnice na grafu: zvolí se dva body, vede se vodorovná úsečka (Δx) a svislá úsečka (Δy). Směrnice je m = Δy/Δx.",
"Gerade aufschalten, dann m und q oben mit den Schiebereglern verändern.": "Přidejte přímku a pak měňte m a q posuvníky nahoře.",
"Gerade, die den Graphen im Punkt (x₀ | {0}) berührt. Die Steigung der Tangente ist gleich {1}. Die Tangente ist die beste lineare Näherung des Graphen an dieser Stelle.": "Přímka, která se grafu dotýká v bodě (x₀ | {0}). Směrnice tečny je rovna {1}. Tečna je nejlepší lineární aproximace grafu v tomto bodě.",
"Gerade, die den Graphen in zwei Punkten schneidet. Die Steigung der Sekante entspricht dem Differenzenquotienten — der durchschnittlichen Änderungsrate.": "Přímka, která protíná graf ve dvou bodech. Směrnice sečny odpovídá diferenčnímu podílu — průměrné rychlosti změny.",
"Geradengleichung": "Rovnice přímky",
"Geradengleichung:": "Rovnice přímky:",
"Gesucht": "Hledáno",
"Gesucht: x mit f{0}(x) = f{1}(x)": "Hledáme x, pro které f{0}(x) = f{1}(x)",
"Gesucht: x mit {0} = {1}": "Hledáme x, pro které {0} = {1}",
"Gesucht: x, bei dem {0} → ±∞": "Hledat x, kde {0} → ±∞",
"Gesucht: x₁, x₂ mit": "Hledáme x₁, x₂, pro něž platí",
"Gesucht: x₁, x₂ mit x₁ + x₂ = {0} und x₁ · x₂ = {1}": "Hledáme: x₁, x₂ s x₁ + x₂ = {0} a x₁ · x₂ = {1}",
"Gibt an, wie oft der Linearfaktor (x − x₀) im Produkt vorkommt. Einfache NS (n={0}): Graph kreuzt die x-Achse. Doppelte NS (n={1}): Graph berührt die x-Achse (Wendepunkt bei der NS möglich).": "Udává, kolikrát se kořenový činitel (x − x₀) vyskytuje v součinu. Jednoduchý nulový bod (n={0}): graf protíná osu x. Dvojnásobný nulový bod (n={1}): graf se dotýká osy x (v nulovém bodě je možný inflexní bod).",
"Gibt den absoluten (nicht-negativen) Wert von x zurück: |x| = x für x ≥ {0}, |x| = −x für x {1} {2}. Graph: V-förmig mit Knick bei x = {3}. Nicht differenzierbar bei x = {4}.": "Vrací absolutní (nezápornou) hodnotu x: |x| = x pro x ≥ {0}, |x| = −x pro x {1} {2}. Graf: tvar V s lomem v x = {3}. Nemá derivaci v x = {4}.",
