"Ein Produkt ist eine Fläche: Jede Klammer ist eine Seite des Rechtecks, die Teilrechtecke sind die Teilprodukte.": "Součin je obsah: každá závorka je jedna strana obdélníku, dílčí obdélníky jsou dílčí součiny.",
"<0>Mit Zahlen und zwei Variablen</0>{1}": "<0>S čísly a dvěma proměnnými</0>{1}",
"<0>Zwei Klammern mit Kacheln</0>{1}": "<0>Dvě závorky s dlaždicemi</0>{1}",
"<0>Mit negativen Gliedern</0>{1}": "<0>Se zápornými členy</0>{1}",
"<0>Der Würfel</0>{1}": "<0>Krychle</0>{1}",
"Die Formel bleibt dieselbe: a = {0}x und b = {1}y. Darum {2}x² − {3}xy + {4}y².": "Vzorec zůstává stejný: a = {0}x a b = {1}y. Proto {2}x² − {3}xy + {4}y².",
"Das Quadrat mit der Seite a + b besteht aus dem Quadrat a², dem Quadrat b² und zwei Rechtecken ab.": "Čtverec o straně a + b se skládá ze čtverce a², čtverce b² a dvou obdélníků ab.",
"Vom Quadrat a² werden zwei Streifen ab abgezogen. Das Eckquadrat b² wurde dabei zweimal weggenommen und kommt einmal zurück.": "Od čtverce a² se odečtou dva pruhy ab. Rohový čtverec b² byl přitom odebrán dvakrát, a proto se jednou vrací.",
"Ein Streifen wird umgelegt: Übrig bleibt a² − b², ein Rechteck mit den Seiten a + b und a − b.": "Jeden pruh se přeloží: zbyde a² − b², obdélník o stranách a + b a a − b.",
"Jede Kachel ist eine Fläche: ein x², fünf x und sechs {0}.": "Každá dlaždice je obsah: jedno x², pět x a šest {0}.",
"Negative Teilflächen werden abgezogen. Rot sind die negativen Kacheln.": "Záporné dílčí obsahy se odečítají. Červené jsou záporné dlaždice.",
"Der Würfel mit der Kante a + b besteht aus a³, b³, drei Quadern a²b und drei Quadern ab².": "Krychle o hraně a + b se skládá z a³, b³, tří kvádrů a²b a tří kvádrů ab².",
"Tippe auf «Beispiel», dann wird es vorgerechnet und gezeichnet.": "Klepni na „Příklad“ a příklad se vypočítá a nakreslí.",
"Distributivgesetz": "Distributivní zákon",
