"Richtig: {0} von {1}": "Správně: {0} z {1}",
"Das ist nicht gleichwertig zur Aufgabe – rechne noch einmal nach.": "To není rovnocenné se zadáním – přepočítej to ještě jednou.",
"Faktorisieren heisst: aus der Fläche wieder ein Rechteck legen. Die Seitenlängen sind die Faktoren.": "Rozložit na součin znamená: z obsahu znovu složit obdélník. Délky stran jsou činitelé.",
"<0>Gemeinsamer Faktor</0>{1}": "<0>Společný činitel</0>{1}",
