"Faktorisiere:": "Rozlož na součin:",
"Fehlt dem Quadrat nur noch ein kleines Eckquadrat, dann ergänzt man genau dieses – und hat ein vollständiges Quadrat.": "Chybí-li čtverci jen malý rohový čtverec, pak se přesně ten doplní – a máme úplný čtverec.",
"<0>Einfaches Beispiel</0>{1}": "<0>Jednoduchý příklad</0>{1}",
"<0>Mit negativem Glied</0>{1}": "<0>Se záporným členem</0>{1}",
"<0>Mit Faktor vor x²</0>{1}": "<0>S koeficientem před x²</0>{1}",
"Das Quadrat x² mit zwei Rechtecken {0}x lässt eine Ecke {1}² = {2} offen. Man ergänzt sie und zieht sie wieder ab.": "Čtverec x² se dvěma obdélníky {0}x nechává otevřený roh {1}² = {2}. Doplníme ho a znovu odečteme.",
"Die Hälfte von −{0} ist −{1}; das Quadrat ergänzen: (x − {2})² − {3}.": "Polovina z −{0} je −{1}; doplníme čtverec: (x − {2})² − {3}.",
"Zuerst die {0} ausklammern, dann ergänzen: {1}(x − {2})² − {3}. Der Scheitelpunkt ist {4}.": "Nejdřív vytkneme {0}, potom doplníme: {1}(x − {2})² − {3}. Vrchol je {4}.",
"Schreibe mit vollständigem Quadrat:": "Zapiš pomocí úplného čtverce:",
"Die Zeilen des Pascal'schen Dreiecks sind die Koeffizienten von (a + b)ⁿ.": "Řádky Pascalova trojúhelníku jsou koeficienty (a + b)ⁿ.",
"<0>Fünfte Potenz</0>{1}": "<0>Pátá mocnina</0>{1}",
