"Wurzel und rationale Hochzahl": "Odmocnina a racionální exponent",
"Gleichung und Äquivalenzumformung": "Rovnice a ekvivalentní úprava",
"Quadratische Gleichung (Lösungsformel, Diskriminante)": "Kvadratická rovnice (vzorec, diskriminant)",
"Bruchgleichung und Scheinlösung": "Rovnice se zlomky a zdánlivý kořen",
