"Neue Ziehung": "Nový tah",
"Gezogene Kugeln bleiben draussen. Beim ersten Zug hat man n Möglichkeiten, beim zweiten n − {0}, … beim k-ten n − k + {1}. Die Reihenfolge zählt. Multiplikationsprinzip: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.": "Vytažené koule zůstávají venku. Při prvním tahu je n možností, při druhém n − {0}, … při k-tém n − k + {1}. Pořadí záleží. Pravidlo součinu: n · (n − {2}) · … · (n − k + {3}) = n!/(n − k)!.",
"Alle {0} Möglichkeiten sind gleich wahrscheinlich.": "Všech {0} možností je stejně pravděpodobných.",
