"Wahrscheinlichkeit für das gezogene Ergebnis:": "Pravděpodobnost vytaženého výsledku:",
"Jede gezogene Kugel wird zurückgelegt, darum hat man bei jedem der k Züge wieder n Möglichkeiten. Die Reihenfolge zählt: ({0}, {1}) und ({2}, {3}) sind verschieden. Multiplikationsprinzip: n · n · … · n mit k Faktoren.": "Každá vytažená koule se vrací, takže při každém z k tahů je opět n možností. Pořadí záleží: ({0}, {1}) a ({2}, {3}) jsou různé. Pravidlo součinu: n · n · … · n s k činiteli.",
"Es zählt nur, welche Kugeln gezogen wurden (wie bei einem Griff in die Urne). Jede Auswahl von k Kugeln lässt sich auf k! Arten anordnen. Darum teilt man die Zahl der Variationen n!/(n − k)! durch k!. Das ist der Binomialkoeffizient «n über k».": "Počítá se jen to, které koule byly vytaženy (jako při sáhnutí do urny). Každý výběr k koulí lze uspořádat k! způsoby. Proto se počet variací n!/(n − k)! dělí k!. To je binomický koeficient „n nad k“.",
"Die Kugeln werden zurückgelegt, aber nur die gezogene Menge zählt: Kugeln dürfen mehrfach vorkommen, die Reihenfolge nicht. Zählen mit Sternen und Strichen: k Kugeln («Sterne») und n − {0} Trennstriche zwischen den n Nummern ergeben n + k − {1} Plätze, auf denen man k für die Sterne wählt.": "Koule se vracejí, ale počítá se jen vytažená skupina: koule se mohou opakovat, pořadí nezáleží. Počítání pomocí hvězdiček a čárek: k koulí („hvězdičky“) a n − {0} oddělovacích čárek mezi n čísly dává n + k − {1} míst, z nichž se vybere k pro hvězdičky.",
"Die Möglichkeiten sind nicht gleich wahrscheinlich: Mengen mit verschiedenen Kugeln kommen häufiger vor.": "Možnosti nejsou stejně pravděpodobné: skupiny s různými koulemi se vyskytují častěji.",
"k = n: Alle Kugeln werden gezogen (Permutation).": "k = n: vytáhnou se všechny koule (permutace).",
"Ohne Zurücklegen: Jede Auswahl lässt sich auf k! Arten anordnen. Variationen = k! · Kombinationen:": "Bez vracení: každý výběr lze uspořádat k! způsoby. Variace = k! · kombinace:",
"Mit Zurücklegen gibt es meistens mehr Möglichkeiten als ohne.": "S vracením je obvykle více možností než bez vracení.",
"Die vier Urnenmodelle im Vergleich: {0} Kugeln, {1} werden gezogen": "Čtyři modely urny ve srovnání: {0} koulí, tahá se {1}",
"mit Reihenfolge": "s pořadím",
"ohne Reihenfolge": "bez pořadí",
