"<0>Schritt {1}:</0> Durch {2} dividieren: zuerst {3} ausklammern, dann kürzen.": "<0>Krok {1}:</0> vydělit {2}: nejprve vytknout {3}, potom zkrátit.",
"<0>Schritt {1}:</0> Grenzwert {2} bilden: alle Summanden mit {3} fallen weg.": "<0>Krok {1}:</0> vypočítat limitu {2}: všechny sčítance s {3} vymizí.",
"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben.": "Nahoře graf funkce f, dole graf derivace f′. Přetáhni bod: výška dolního bodu je směrnice tečny nahoře.",
"Wo f steigt, ist f′ positiv (grün), wo f fällt, ist f′ negativ (orange). Bei waagrechter Tangente ist f′ = {0}.": "Kde f roste, je f′ kladná (zeleně); kde f klesá, je f′ záporná (oranžově). Při vodorovné tečně je f′ = {0}.",
