"<0>Schritt {1}:</0> Das Intervall wird in {2} gleich breite Streifen geteilt.": "<0>Krok {1}:</0> Interval se rozdělí na {2} pruhů stejné šířky.",
"<0>Schritt {1}:</0> Auf {2} wächst {3}. Darum ist der rechte Randpunkt eines Streifens der höchste.": "<0>Krok {1}:</0> Na {2} je {3} rostoucí. Proto je pravý krajní bod pruhu nejvyšší.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren und die Summenformeln verwenden:": "<0>Krok {1}:</0> Dosadit {2}, roznásobit a použít vzorce pro součty:",
"<0>Schritt {1}:</0> Grenzwert für {2}: Alle Summanden mit {3} gehen gegen {4}.": "<0>Krok {1}:</0> Limita pro {2}: všechny sčítance s {3} jdou k {4}.",
"Kontrolle mit der Stammfunktion: {0}.": "Kontrola primitivní funkcí: {0}.",
"<0>Differentialrechnung</0><1>Differenzenquotient, Sekante und Tangente, Graphisches Ableiten, Ableitungsregeln, Kurvendiskussion</1>": "<0>Diferenciální počet</0><1>Diferenční podíl, sečna a tečna, grafické derivování, pravidla derivování, vyšetřování funkce</1>",
"<0>Integralrechnung</0><1>Ober- und Untersummen, Integralfunktion und Hauptsatz, Stammfunktion mit Regeln, Flächen zwischen Kurven, Rotationskörper</1>": "<0>Integrální počet</0><1>Horní a dolní součty, integrální funkce a základní věta, primitivní funkce s pravidly, obsahy mezi křivkami, rotační tělesa</1>",
"<0>Algebra</0><1>Binomische Formeln, Ausmultiplizieren, Faktorisieren, quadratische Ergänzung, Potenzen, Wurzeln, Logarithmen, Bruchterme, Gleichungen und Gleichungssysteme als Bild</1>": "<0>Algebra</0><1>Vzorce pro úpravu výrazů, roznásobování, rozklad na součin, doplnění na čtverec, mocniny, odmocniny, logaritmy, zlomky s proměnnou, rovnice a soustavy rovnic jako obrázek</1>",
"<0>Wahrscheinlichkeit & Statistik</0><1>Zufallsexperimente zum Mitverfolgen: Würfel, Galtonbrett, π, Ziegenproblem, Grenzwertsatz, Konfidenzintervalle</1>": "<0>Pravděpodobnost a statistika</0><1>Náhodné pokusy k sledování: kostky, Galtonovo prkno, π, Monty Hallův problém, centrální limitní věta, intervaly spolehlivosti</1>",
"<0>Finanzmathematik</0><1>Zeitstrahl und Konten, Summenzeichen, Sparplan, Kredit mit Tilgungsplan, Zeitwert, Marchzins, konformer Zins</1>": "<0>Finanční matematika</0><1>Časová osa a účty, znak sumy, spořicí plán, úvěr se splátkovým kalendářem, současná hodnota, úrok za dny, ekvivalentní úroková sazba</1>",
"Das Intervall wird in {0} gleich breite Streifen der Breite {1} geteilt. Die <2>Untersumme</2> nimmt in jedem Streifen den kleinsten, die <3>Obersumme</3> den grössten Funktionswert als Höhe des Rechtecks.": "Interval se rozdělí na {0} pruhů stejné šířky {1}. <2>Dolní součet</2> bere v každém pruhu nejmenší funkční hodnotu jako výšku obdélníku, <3>horní součet</3> největší.",
"Für {0} streben beide Summen gegen {1}.": "Pro {0} oba součty jdou k {1}.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren.": "<0>Krok {1}:</0> Dosadit {2} a roznásobit.",
"Oben der Graph von f mit der gefärbten Fläche von a bis x, unten die Integralfunktion Fa(x) = ∫ f. Ziehe den Punkt x: Der untere Punkt zeigt, wie viel Fläche bis dahin gesammelt wurde.": "Nahoře: graf f s vybarvenou plochou od a do x; dole: integrální funkce Fa(x) = ∫ f. Přetáhni bod x: dolní bod ukazuje, kolik plochy se dosud nasbíralo.",
"Die Steigung von Fa an der Stelle x ist {0}: Wo f positiv ist, steigt Fa (grün), wo f negativ ist, fällt Fa (orange). Das ist der Hauptsatz.": "Směrnice Fa v bodě x je {0}: kde je f kladná, Fa roste (zeleně), kde je f záporná, Fa klesá (oranžově). To je základní věta.",
