"<0>Schritt {1}:</0> Hauptsatz: Obere Grenze einsetzen, untere Grenze einsetzen, subtrahieren.": "<0>Krok {1}:</0> Základní věta: dosadit horní mez, dosadit dolní mez, odečíst.",
