"Die Fläche zwischen f und der x-Achse (oder zwischen f und g) wird an den Schnittstellen in Stücke geteilt. Stücke über der Achse (bzw. über g) sind grün, darunter orange.": "Plocha mezi f a osou x (nebo mezi f a g) se v průsečících rozdělí na kousky. Kousky nad osou (resp. nad g) jsou zelené, pod ní oranžové.",
"Flächen zählen immer positiv: Beim Integral heben sich grüne und orange Stücke teilweise auf, bei der Fläche nicht.": "Plochy se vždy počítají kladně: v integrálu se zelené a oranžové kousky částečně ruší, v ploše ne.",
