"Dreht man den Graphen von {0} zwischen {1} und {2} um die {3}-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben mit dem Radius {4} und der Dicke {5}. Jede Scheibe hat das Volumen {6}.": "Otočíme-li graf {0} mezi {1} a {2} kolem osy {3}, vznikne těleso z mnoha tenkých kotoučů o poloměru {4} a tloušťce {5}. Každý kotouč má objem {6}.",
"<0>Schritt {1}:</0> {2} quadrieren.": "<0>Krok {1}:</0> Umocnit {2} na druhou.",
