"Parabel und Gerade, Parabel aus Punkten": "Parabola a přímka, parabola z bodů",
"Eine quadratische Funktion {0} = ax² + bx + c hat eine Parabel als Graph. Der Faktor a streckt die Normalparabel (bei a {1} {2} gespiegelt), der Scheitel S ist der höchste oder tiefste Punkt.": "Kvadratická funkce {0} = ax² + bx + c má za graf parabolu. Koeficient a natahuje základní parabolu (při a {1} {2} je překlopena), vrchol S je nejvyšší nebo nejnižší bod.",
"Ziehe den Scheitel S, den roten Punkt (a), den Achsenabschnitt c oder die Nullstellen N. Standard-, Scheitel- und Nullstellenform beschreiben dieselbe Parabel.": "Přetáhni vrchol S, červený bod (a), úsek c nebo nulové body N. Obecný, vrcholový a součinový tvar popisují touž parabolu.",
