"Gerade und Parabel: Gleichsetzen gibt eine quadratische Gleichung, deren Diskriminante die Anzahl der Schnittpunkte bestimmt (Sekante, Tangente, Passante). Umgekehrt legen drei Punkte, oder Scheitel und Punkt, oder zwei Nullstellen und ein Punkt eine Parabel fest.": "Přímka a parabola: Položením sobě rovných vznikne kvadratická rovnice, jejíž diskriminant určuje počet průsečíků (sečna, tečna, vnější přímka). Naopak tři body, nebo vrchol a bod, nebo dva nulové body a bod určují parabolu.",
"Ziehe die Punkte und Griffe. Mit «Gerade berühren lassen» wird die Gerade bei gleicher Steigung zur Tangente.": "Přetáhni body a úchyty. Tlačítkem «Nechat přímku dotknout se» se přímka při stejné směrnici stane tečnou.",
