"<0>Gemeinsame Punkte:</0> Alle Potenzfunktionen gehen durch {1} und {2} und, weil {3} ungerade ist, durch {4}.": "<0>Společné body:</0> Všechny mocninné funkce procházejí body {1} a {2} a protože {3} je liché, také bodem {4}.",
"<0>Monotonie und Verlauf:</0> Der Graph steigt auf ganz {1} (streng monoton wachsend).": "<0>Monotonie a průběh:</0> Graf roste na celém {1} (ryze monotónně rostoucí).",
