"Erlaubt sind a·(x−v)^n + h, a/(x−v)^n + h, a·√(x−v) + h und (x−v)^(m/n) + h.": "Povoleny jsou a·(x−v)^n + h, a/(x−v)^n + h, a·√(x−v) + h a (x−v)^(m/n) + h.",
