"Die Wurzelfunktion ⁿ√x ist die Umkehrfunktion von xⁿ: Ihr Graph ist das Spiegelbild an der Winkelhalbierenden y = x. In Potenzschreibweise ist ⁿ√x = x^({0}/n), allgemein x^(m/n) = ⁿ√(xᵐ).": "Odmocninná funkce ⁿ√x je inverzní funkce k xⁿ: Její graf je obraz zrcadlený podle osy kvadrantů y = x. V mocninném zápisu je ⁿ√x = x^({0}/n), obecně x^(m/n) = ⁿ√(xᵐ).",
"Ziehe den Punkt P auf der Potenzfunktion: Sein Spiegelbild P′ liegt auf der Wurzelfunktion. Wähle n und einen Zähler m für den rationalen Exponenten.": "Táhni bod P po mocninné funkci: Jeho zrcadlový obraz P′ leží na odmocninné funkci. Zvol n a čitatele m pro racionální exponent.",
