"Gleichung {0} = y₀ lösen: Die Potenz wird isoliert, dann entscheidet die Fallunterscheidung (gerade/ungerade, Wurzel, negative rechte Seite), wie viele Lösungen es gibt. Die Lösungen sind die Schnittstellen mit der Geraden y = y₀.": "Řešení rovnice {0} = y₀: Mocnina se izoluje, pak rozlišení případů (sudá/lichá, odmocnina, záporná pravá strana) rozhodne, kolik je řešení. Řešení jsou průsečíky s přímkou y = y₀.",
"Ziehe die orange Gerade auf und ab und beobachte, wann es zwei, eine oder keine Lösung gibt. Der Rechenweg rechts passt sich an.": "Táhni oranžovou přímku nahoru a dolů a sleduj, kdy jsou dvě řešení, jedno, nebo žádné. Postup vpravo se přizpůsobuje.",
