"Gerade Potenz, rechts positiv: <0>zwei Lösungen</0>, die Quadratwurzel mit beiden Vorzeichen.": "Sudá mocnina, vpravo kladné číslo: <0>dvě řešení</0>, druhá odmocnina s oběma znaménky.",
