"<0>Schritt {1}: Fallunterscheidung.</0> Links steht die {2}-te Potenz von {3}, rechts {4}.": "<0>Krok {1}: Rozlišení případů.</0> Vlevo je {2}. mocnina {3}, vpravo {4}.",
