"Ein Bruch mit Zähler {0} wird nie {1}: <2>keine Lösung</2>.": "Zlomek s čitatelem {0} se nikdy nerovná {1}: <2>žádné řešení</2>.",
"<0>Schritt {1}:</0> Die Potenz isolieren: {2} subtrahieren.": "<0>Krok {1}:</0> Izolovat mocninu: odečíst {2}.",
