"Beide Seiten mit dem Kehrwert des Exponenten potenzieren: {0}. Gerader Zähler: beide Vorzeichen.": "Obě strany umocnit na převrácenou hodnotu exponentu: {0}. Sudý čitatel: obě znaménka.",
"Die Potenz ist {0}, also ist die Basis {1}: <2>eine Lösung</2>.": "Mocnina je {0}, proto je základ {1}: <2>jedno řešení</2>.",
"Gerade Potenz, rechts positiv: <0>zwei Lösungen</0>, die {1}-te Wurzel mit beiden Vorzeichen.": "Sudá mocnina, vpravo kladné číslo: <0>dvě řešení</0>, {1}. odmocnina s oběma znaménky.",
"Kehrwert bilden, dann die {0}-te Wurzel ziehen.": "Vytvořit převrácenou hodnotu, pak odmocnit {0}. odmocninou.",
